CREATE TABLE "book_work_groups" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "canonical_title" VARCHAR(255) NOT NULL, "normalized_title" VARCHAR(255) NOT NULL, "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "book_work_groups_pkey" PRIMARY KEY ("id"));
ALTER TABLE "books" ADD COLUMN "work_group_id" UUID;
CREATE INDEX "books_work_group_id_idx" ON "books"("work_group_id");
CREATE INDEX "book_work_groups_normalized_title_idx" ON "book_work_groups"("normalized_title");
ALTER TABLE "books" ADD CONSTRAINT "books_work_group_id_fkey" FOREIGN KEY ("work_group_id") REFERENCES "book_work_groups"("id") ON DELETE SET NULL;
CREATE TABLE "duplicate_review_drafts" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "input_metadata" JSONB NOT NULL DEFAULT '{}', "candidates" JSONB NOT NULL DEFAULT '[]', "classification" VARCHAR(40) NOT NULL, "similarity_score" DECIMAL(4,3) NOT NULL DEFAULT 0, "explanation" JSONB NOT NULL DEFAULT '{}', "decision" VARCHAR(40), "selected_book_id" UUID, "selected_variant_id" UUID, "reviewed_by_user_id" UUID, "reviewed_at" TIMESTAMPTZ(6), "created_by_user_id" UUID NOT NULL, "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "duplicate_review_drafts_pkey" PRIMARY KEY ("id"));
